package org.example.backend.controller;
import org.example.backend.service.*;
import org.example.backend.entity.*;
import org.example.backend.security.*;
import org.example.backend.config.GlobalExceptionHandler;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.http.MediaType;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class WorkflowEndpointBehaviorTest {
    @Test void countersignEndpointsKeepBusinessFiltersAndOptionalReviewPayloads() throws Exception{ApprovalCountersignService service=mock(ApprovalCountersignService.class);var mvc=MockMvcBuilders.standaloneSetup(new ApprovalCountersignController(service)).build();mvc.perform(get("/approval-countersigns").param("businessType","reservation").param("businessId","7").param("assigneeName","甲").param("status","待处理")).andExpect(status().isOk());mvc.perform(post("/approval-countersigns").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());mvc.perform(post("/approval-countersigns/7/complete")).andExpect(status().isOk());mvc.perform(post("/approval-countersigns/7/cancel")).andExpect(status().isOk());verify(service).listCountersigns("reservation","7","甲","待处理");verify(service).createCountersign(any());verify(service).completeCountersign(7L,null);verify(service).cancelCountersign(7L,null);}
    @Test void adjustmentEndpointsForwardCreateUpdateAndApprovalIdentity() throws Exception{ScheduleAdjustmentService service=mock(ScheduleAdjustmentService.class);var mvc=MockMvcBuilders.standaloneSetup(new ScheduleAdjustmentController(service)).build();mvc.perform(get("/schedule-adjustments")).andExpect(status().isOk());mvc.perform(post("/schedule-adjustments").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());mvc.perform(put("/schedule-adjustments/7").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());mvc.perform(post("/schedule-adjustments/7/approve")).andExpect(status().isOk());mvc.perform(post("/schedule-adjustments/7/complete")).andExpect(status().isOk());verify(service).listAdjustments();verify(service).createAdjustment(any());verify(service).updateAdjustment(eq(7L),any());verify(service).approveAdjustment(7L);verify(service).completeAdjustment(7L);}
    @Test void studentClientRoutesPreserveLabAndDeviceIdentity() throws Exception{StudentClientService service=mock(StudentClientService.class);var mvc=MockMvcBuilders.standaloneSetup(new StudentClientController(service)).build();mvc.perform(post("/api/student-clients/online").contentType(MediaType.APPLICATION_JSON).content("{\"labId\":7,\"studentDeviceId\":\"PC1\"}")).andExpect(status().isOk());mvc.perform(post("/student-clients/offline").contentType(MediaType.APPLICATION_JSON).content("{\"labId\":7,\"studentDeviceId\":\"PC1\"}")).andExpect(status().isOk());mvc.perform(get("/api/student-clients").param("labId","7")).andExpect(status().isOk());verify(service).online(argThat(client->client.getLabId()==7&&"PC1".equals(client.getStudentDeviceId())));verify(service).offline(argThat(client->client.getLabId()==7));verify(service).listByLabId(7L);}
    @Test void loanWritesUseAuthenticatedOperatorInsteadOfUntrustedBodyFields() throws Exception{ConsumableLoanService service=mock(ConsumableLoanService.class);var mvc=MockMvcBuilders.standaloneSetup(new ConsumableLoanController(service)).build();mvc.perform(get("/consumables/loans")).andExpect(status().isOk());mvc.perform(get("/consumables/loans/7")).andExpect(status().isOk());mvc.perform(post("/consumables/loans").requestAttr(JwtAuthenticationFilter.AUTH_USERNAME_ATTRIBUTE,"admin").contentType(MediaType.APPLICATION_JSON).content("{\"consumableId\":1,\"quantity\":2,\"operator\":\"attacker\"}")).andExpect(status().isOk());mvc.perform(post("/consumables/loans/7/return").requestAttr(JwtAuthenticationFilter.AUTH_USERNAME_ATTRIBUTE,"admin").contentType(MediaType.APPLICATION_JSON).content("{\"quantity\":1}")).andExpect(status().isOk());verify(service).list();verify(service).get(7L);verify(service).borrow(any(),eq("admin"));verify(service).returnItems(eq(7L),any(),eq("admin"));}
    @Test void aiDecisionRequiresNumericAuthenticatedUserAndExplicitBoolean() throws Exception{AiBusinessOperationService service=mock(AiBusinessOperationService.class);var mvc=MockMvcBuilders.standaloneSetup(new AiBusinessActionController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();mvc.perform(post("/ai-assistant/actions/a/decision").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());mvc.perform(post("/ai-assistant/actions/a/decision").requestAttr(AuthenticationAttributes.USER_ID,7).contentType(MediaType.APPLICATION_JSON).content("{\"confirmed\":\"true\"}")).andExpect(status().isBadRequest());mvc.perform(post("/ai-assistant/actions/a/decision").requestAttr(AuthenticationAttributes.USER_ID,7).contentType(MediaType.APPLICATION_JSON).content("{\"conversationId\":\"chat\",\"confirmed\":true}")).andExpect(status().isOk());verify(service).decide(eq(7),eq("chat"),eq("a"),eq(true),any());}
}
